function UISystemHighlightRegionNode:InitNodePosition(node, renderCameraType, particle, isReload)
    renderCameraType = checkNumber(renderCameraType)

    local oldAnchoredPosition = self.ImgHighLight.anchoredPosition
    if renderCameraType >= Constants.GuideNodeCameraType.MainCamera then
        local camera = GuideUtils.GetGuideNodeRenderCameraByType(renderCameraType)
        local v2 = CfUtils.WorldPosition2UIPosition(node.position, self.controller.transform, camera)
        local v3 = Vector3.New(v2.x, v2.y, 0)
        self.ArrowNode.anchoredPosition     = v3
        self.StepIconClick.anchoredPosition = v3
        self.ImgHighLight.anchoredPosition3D  = v3

    else
        local position              = node.position
        self.ArrowNode.position     = position
        self.StepIconClick.position = position
        self.ImgHighLight.position  = position

    end
    
    if particle > 0 and not isReload then
        self.isComplete = false
        cs_coroutine.start(function ()
            local effectFly  = self:GetEffectByType(EffectType.Fly)
            local effectBoom = self:GetEffectByType(EffectType.Boom)
            xTry(function ()
                local newPos = self.ImgHighLight.anchoredPosition
                effectBoom.transform.anchoredPosition = oldAnchoredPosition
                KTool.SetActive(effectBoom.gameObject, true)
                -- local dis = Vector2.Distance(oldAnchoredPosition, newPos)
                local time = 3
                effectFly.transform.anchoredPosition = oldAnchoredPosition
                KTool.SetActive(effectFly.gameObject,  true)
                effectFly.transform:DOAnchorPos(Vector3.New(newPos.x, newPos.y, 0), math.min(0.6, time)):SetEase(Ease.InOutQuad).onComplete = function()
                    KTool.SetActive(effectFly.gameObject,  false)
                    cs_coroutine.start(function ()
                        effectBoom.transform.anchoredPosition = newPos
                        KTool.SetActive(effectBoom.gameObject, true)
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                        KTool.SetActive(effectBoom.gameObject, false)
                        self.isComplete = true
                    end)
                end
                
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                KTool.SetActive(effectBoom.gameObject, false)
                
            end)
            
        end)
        
    end

end

