function UISystemHighlightRegionNode:UpdateArrowRealPosition(node, direction, offsetX, offsetY)
    direction = checkNumber(direction)
    ---@type UnityEngine.RectTransform
    local transform = node.transform
    local sizeDelta = transform.sizeDelta
    local anchoredPosition = self.ArrowNode.anchoredPosition
    offsetX, offsetY = checkNumber(offsetX), checkNumber(offsetY)
    if direction >= 1 and direction <= 2 then
        local flag = direction == 1 and 1 or -1
        self.ArrowNode.anchoredPosition = Vector2.New(anchoredPosition.x + offsetX, anchoredPosition.y + sizeDelta.y * 0.5 * flag + offsetY)
        self.ArrowNode.eulerAngles = Vector3.New(0, 0, direction == 1 and 0 or 180)
    elseif direction >= 3 and direction <= 4 then
        local flag =  direction == 3 and -1 or 1
        self.ArrowNode.anchoredPosition = Vector2.New(anchoredPosition.x + sizeDelta.x * 0.5 * flag + offsetX, anchoredPosition.y + offsetY)
        self.ArrowNode.eulerAngles = Vector3.New(0, 0, direction == 1 and 90 or -90)
    end
end


function UISystemHighlightRegionNode:UpdateHighlightFrameShowState(isShow, node, actionHLParam)
    if isShow then
        -- local isEmpty  = string.isEmpty(actionHLParam)
        local unity_quaternion = Quaternion.unity_quaternion
        local rotation = unity_quaternion.identity
        if not string.isEmpty(actionHLParam) then
            local t = parse_strings(actionHLParam, ":")
            rotation = Quaternion.Euler(checkNumber(t[1]), checkNumber(t[2]), checkNumber(t[3]))
        end
        self.ImgHighLight.localRotation = rotation
        -- local rotation = isEmpty and Quaternion.unity_quaternion.identity or 
    --    self.ImgHighLight.transform:SetRo 
    end
    self:UpdateImgHighLightShowState(isShow)
end

function UISystemHighlightRegionNode:UpdateImgHighLightShowState(isShow)
    KTool.SetActive(self.ImgHighLight.gameObject, isShow)
    if isShow and self.ImgHighLightAnimator then
        self.ImgHighLightAnimator:Rebind()
        self.ImgHighLightAnimator:Play(PlayHash)
    end
end

