function UISystemHighlightRegionNode:GetEffectByType(effectType)
    local go = self.effectGos[effectType]
    if isNull(go) then
        local path = EffectPath[effectType]
        local name = string.stripExtension(string.stripFileName(path))
        go = self.controller.transform:Find(name)
        if isNull(go) then
            go = GameUtils.LoadBundleAsync(EffectPath[effectType], self.controller.gameObject)
        end
        -- local particleSystems = go.gameObject:GetComponentsInChildren(typeof(ParticleSystem))

        self.effectGos[effectType] = go
        -- self.particleSystems[effectType] = particleSystems
    end
    return go
end

